<h3 class="wp-block-heading">Khu du lịch Cồn Ấu Cần Thơ</h3>



<p>Khu du lịch này hiện <strong>đang nâng cấp, tu sửa</strong> lại do tập đoàn Vingroup đầu tư.</p>



<h3 class="wp-block-heading">Vườn ca cao Mười Cương</h3>



<p>Vườn ca cao Mười Cương là cơ sở sản xuất truyền thống socola và những sản phẩm liên quan ca cao. Đặc biệt, phía sau là một vườn ca cao với hàng nghìn gốc ca cao được trồng. Đến đây, bạn sẽ được tận mắt chứng kiến các công đoạn làm ca cao truyền thống là như thế nào.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/vườn-ca-cao-mười-cương-cần-thơ-1024x682.jpg" alt="Vườn ca cao Mười Cương Cần Thơ" class="wp-image-3724" srcset="https://media.huynhhieutravel.com/vườn-ca-cao-mười-cương-cần-thơ.jpg 1024w, https://media.huynhhieutravel.com/vườn-ca-cao-mười-cương-cần-thơ-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Vườn ca cao Mười Cương Cần Thơ</figcaption></figure>



<p>Ngoài trồng ca cao thì nơi đây còn trồng nhiều loại cây ăn quả khác như mận, bưởi, mít,&#8230; Bạn còn có thể mua sắm các sản phẩm ca cao ở đây như <strong>socola, rượu ca cao, bột ca cao</strong>,&#8230; để về làm quà cho người thân và bạn bè.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="853" src="https://media.huynhhieutravel.com/san-pham-cacao-o-vuon-can-tho-1024x853.jpg" alt="Sản phẩm ca cao ở vườn Cần Thơ" class="wp-image-2417"/><figcaption>Sản phẩm ca cao ở vườn Cần Thơ</figcaption></figure>



<h4 class="wp-block-heading">Giá vé vườn ca cao Mười Cương</h4>



<p>Giá vé vào cổng: <strong>30.000đ/vé</strong>.</p>



<h4 class="wp-block-heading">Giờ mở cửa vườn ca cao Mười Cương</h4>



<p>Thời gian mở cửa: <strong>6h00 &#8211; 12h00</strong>. Tuy vậy, bạn nên đến sớm để được chứng kiến tận mắt chủ vườn thuyết minh và làm ca cao. Nếu đến trễ ban phải nhờ hướng dẫn viên đi tour làm cho bạn thấy.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="719" src="https://media.huynhhieutravel.com/cay-ca-cao-o-vuon-muoi-cuong-1024x719.jpg" alt="Cây ca cao ở vườn Mười Cường" class="wp-image-2392" srcset="https://media.huynhhieutravel.com/cay-ca-cao-o-vuon-muoi-cuong-1024x719.jpg 1024w, https://media.huynhhieutravel.com/cay-ca-cao-o-vuon-muoi-cuong-370x260.jpg 370w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Cây ca cao ở vườn Mười Cường</figcaption></figure>



