<h2 class="wp-block-heading">Củi Coffee &amp; Homestay Cần Thơ</h2>



<p>Củi Coffee &amp; Homestay là một homestay với chất liệu gỗ là chủ đạo. Một phần của quán là màu nâu tự nhiên của gỗ, phần còn lại là màu trắng đen chủ đạo mang xu hướng trẻ trung hơn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/củi-coffee-homestay-1024x682.jpg" alt="Củi Coffee &amp; Homestay Cần Thơ" class="wp-image-3625" srcset="https://media.huynhhieutravel.com/củi-coffee-homestay.jpg 1024w, https://media.huynhhieutravel.com/củi-coffee-homestay-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Củi Coffee &amp; Homestay</figcaption></figure>



<p>Quán cũng có khá nhiều cây xanh. Sân thượng có dàn ghế nhìn ra bên ngoài khá ổn. Quán có nhiều góc riêng để bạn làm việc. Không gian khá yên tĩnh. Lợi thế của quán vừa là homestay vừa là quán cafe nên có nhiều loại nước uống phục vụ ngay tại nơi ở. Bạn cũng có thể dùng một số món ăn ở đây như mì gói, nuôi xào bò,&#8230;</p>



<p>Điểm cộng khác của quán là <strong>tủ sách</strong>. Quán có một tủ sách riêng với nhiều cuốn sách thú vị. Bạn có thể mượn đọc ngay tại quán.</p>



<h3 class="wp-block-heading" id="mce_2">Mức giá Củi Coffee &amp; Homestay</h3>



<ul class="wp-block-list"><li><strong>Phòng 2 người</strong>: 250.000đ/phòng.</li><li><strong>Phòng 3 người</strong>: 350.000đ/phòng.</li></ul>



