INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (3198, 'Nhà cổ Bình Thủy Cần Thơ | LỊCH SỬ | KIẾN TRÚC | GIÁ vé tham quan', 'nha-co-binh-thuy', '
<p><strong>Nhà cổ Bình Thủy ở Cần Thơ</strong> là <strong>một trong ba ngôi nhà cổ nổi tiếng</strong> nhất miền Tây. Lịch sử của căn nhà khoảng <strong>150 năm</strong> nhưng còn giữ khá <strong>nguyên vẹn</strong>. Căn nhà từng là <strong>phim trường</strong> của nhiều bộ <strong>phim nổi tiếng</strong> như <strong>Người Đẹp Tây Đô</strong>, <strong>The Lover</strong> (Năm 1992),&#8230; Bên cạnh đó, <strong>kiến trúc</strong> căn nhà cũng khá đặt biệt và nội thất còn nguyên vẹn đến ngày nay. Tất cả tạo thành một <strong>địa điểm du lịch Cần Thơ hấp dẫn</strong> du khách tham quan.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/hình-ảnh-nhà-cổ-ở-bình-thủy-1024x682.jpg" alt="Hình ảnh của ngôi nhà" class="wp-image-3605" srcset="https://media.huynhhieutravel.com/hình-ảnh-nhà-cổ-ở-bình-thủy.jpg 1024w, https://media.huynhhieutravel.com/hình-ảnh-nhà-cổ-ở-bình-thủy-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Hình ảnh của ngôi nhà</figcaption></figure>



<h2 class="wp-block-heading">Lịch sử nhà cổ Bình Thủy</h2>



<p>Nhà cổ Bình Thủy là nhà của gia tộc dòng họ Dương. Nó được xây dựng vào năm 1870 với kiến trúc sơ xài là gian nhà gỗ bình thường. Sau đó khoảng những năm 1904 được tu bổ lại hoàn toàn và mãi đến năm 1911 mới hoàn thiện. Ngôi nhà là sự kết hợp kiến trúc Đông Tây khá kỳ lạ và hiện đại lúc bấy giờ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/thuyết-minh-nhà-cổ-Bình-Thủy-1024x682.jpg" alt="Thuyết minh nhà cổ Bình Thủy" class="wp-image-3607" srcset="https://media.huynhhieutravel.com/thuyết-minh-nhà-cổ-Bình-Thủy.jpg 1024w, https://media.huynhhieutravel.com/thuyết-minh-nhà-cổ-Bình-Thủy-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Thuyết minh nhà cổ Bình Thủy</figcaption></figure>



<p>Gia đình họ Dương lúc bấy giờ sau 3 đời làm thương gia làm ăn trở nên phát đạt nhất. Lúc ấy, ông Dương Chấn Kỷ được cho sang Pháp du học. Ông là người thông minh, lại đam mê nghệ thuật, kiến trúc và kể cả phong thủy. Vì thế, ông đã góp phần đặt dấu ấn tạo nên một ngôi nhà độc đáo lưu truyền đến bây giờ với lịch sử khoảng 150 năm.</p>



<p>Năm 1980, nhà cổ Bình Thủy được ông Dương Văn Ngôn mang về trang trí rất nhiều chậu hoa Lan. Thú chơi lan và sự giao lưu rộng rãi của ông góp phần tạo nên biệt hiệu &#8220;Vườn lan Bình Thủy&#8221; cho ngôi nhà lúc bấy giờ.<br></p>



<h2 class="wp-block-heading">Kiến trúc nhà cổ Bình Thủy</h2>



<p>Kiến trúc nhà cổ Bình Thủy mang đậm dấu ấn Đông Tây. Đây là ngôi nhà cổ phá vỡ quy tắc 3 gian truyền thống trước đây ở miền Tây. Với thiết kế chia thành 5 gian nhà. Diện tích ngôi nhà 6000 mét vuông.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/nhà-cổ-bình-thủy-cần-thơ-1024x682.jpg" alt="Kiến trúc cổ kính của nhà cổ" class="wp-image-3608" srcset="https://media.huynhhieutravel.com/nhà-cổ-bình-thủy-cần-thơ.jpg 1024w, https://media.huynhhieutravel.com/nhà-cổ-bình-thủy-cần-thơ-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Kiến trúc cổ kính của nhà cổ</figcaption></figure>



<p>Đặc biệt vào năm 1911, ông Dương Chấn Kỷ là gia chủ lúc bấy giờ của nhà họ Dương du học ở Pháp về. Ông là người đam mê kiến trúc nên đã đưa ra dự án tu bổ lại ngôi nhà của dòng họ Dương. Kiến trúc được phối hợp 2 nền văn hóa Đông Tây với những thiết kế đặc trưng đậm nét.</p>



<p>Đầu tiên là hàng rào cổng được thiết kế với hàng rào sắt chắn ngang với các cột bê tông làm trụ chính. Nếu bạn không biết rõ lịch sử thì cứ tưởng nó là hàng rào của một ngôi nhà hiện đại nào đó.</p>



<p>Vào bên trong bạn sẽ bắt gặp một cổng tam quan theo lối kiến trúc người Hoa. Cổng tam quan chếch về hướng bên phải từ ngoài nhìn vào. Cổng tam quan này có 4 cột trụ lớn với 2 trụ xi măng và 2 trụ làm bằng gỗ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/nhà-cổ-cần-thơ-1024x682.jpg" alt="Một số nội thất xưa và hình ảnh lưu niệm của bộ phim L''amant" class="wp-image-3609" srcset="https://media.huynhhieutravel.com/nhà-cổ-cần-thơ.jpg 1024w, https://media.huynhhieutravel.com/nhà-cổ-cần-thơ-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Một số nội thất xưa và hình ảnh lưu niệm của bộ phim L&#8217;amant</figcaption></figure>



<p>Hệ thống xà của cổng được làm bằng gỗ và mái được lợp bằng ngói men xanh. Bên trên trang trí nhiều hình thù sống động với kỳ lân, cá vàng, hoa lá. Ở đó còn có hai bảng hiệu lớn với một bảng hoa là &#8220;Phước An Hiệu&#8221; và một bảng tiếng Việt là &#8220;Phủ thờ họ Dương&#8221;.</p>



<p>Ngoài sân trước nhà là những hàng gạch tàu được lót khoảng 150 năm về trước nhưng vẫn còn mới tinh tươm. Xung quanh sân vườn là những loài hoa kiểng quý: tùng, dương xỉ, cao, phát tài, sứ,&#8230; Đặc biệt, nơi đây còn có nhiều chậu hoa lan và bonsai quý hiếm. </p>



<p>Những loài hoa kiểng này vừa mang lại không khí sinh động cho khuôn viên nhà. Nó lại vừa mang ý nghĩa phong thủy. Ngoài ra, nó còn tác dụng che chắn tầm nhìn khách đi qua ngôi nhà. Giúp ngôi nhà tránh được cái nhìn soi mói của người lạ.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/nhà-cổ-bình-thủy-ở-cần-thơ-1024x682.jpg" alt="Cánh cửa xanh của ngôi nhà lên hình rất đẹp" class="wp-image-3610" srcset="https://media.huynhhieutravel.com/nhà-cổ-bình-thủy-ở-cần-thơ.jpg 1024w, https://media.huynhhieutravel.com/nhà-cổ-bình-thủy-ở-cần-thơ-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Cánh cửa xanh của ngôi nhà lên hình rất đẹp</figcaption></figure>



<p>Góc sân bên trái từ ngoài nhìn vào là một miếu nhỏ thờ thổ thần. Thêm vào đó là bảy bộ ghế ngồi bằng đá.</p>



<p>Bạn phải bước lên cầu thang cao gần 1m để lên gian nhà chính. Có lẽ vì miền Tây là xứ sở hay ngập nước nên ngôi nhà chủ định xây cao hơn để phòng tránh việc này. Đặc biệt, khi xây gian nhà chính ấy, chủ nhân đã dựa theo kinh nghiệm dân gian. Ngôi nhà lót một lớp muối hột khoảng 10cm dưới nền gạch bông.</p>



<p>Thu pháp lót muối dưới gạch bông vừa xua đuổi côn trùng, mang sự thông thoáng ngôi nhà vừa tránh những tà vật xâm hại theo phong thủy. Xung quanh nhà đều là tường gạch, chỉ có những phú hộ giàu có mới xây nhà bằng tường những năm 1900 bấy giờ.</p>



<p>Mái được lợp tổng cộng bởi 3 lớp. Hai lớp dưới được lợp mỏng hình lồng máng để nhìn lên có sự thông thoáng. Cửa gỗ được thiết kế theo phong cách Art – Nouveau của châu Âu. Khi bước vào ngôi nhà, nếu trời nóng bạn sẽ có cảm giác thông thoáng. Nếu trời lạnh bạn sẽ có cảm giác ấm cúng hơn.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/nhà-cổ-vườn-lan-bình-thủy-1024x682.jpg" alt="Nhà cổ vườn lan Bình Thủy" class="wp-image-3611" srcset="https://media.huynhhieutravel.com/nhà-cổ-vườn-lan-bình-thủy.jpg 1024w, https://media.huynhhieutravel.com/nhà-cổ-vườn-lan-bình-thủy-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Nhà cổ vườn lan Bình Thủy</figcaption></figure>



<p>Trong gian nhà chính có ba bộ bàn ghế với chức năng khác nhau. Một bộ dành tiếp khách, một bộ giành cho cả gia đình ăn cơm cùng nhau và một bộ để gia đình ngồi trò chuyện. Toàn bộ căn nhà được nâng bằng 24 cây xà bằng gỗ căm xe.</p>



<p>Bên phải gian nhà từ ngoài nhìn vào là 2 bộ bình bông lớn cỡ người thật. Trên tường là những tấm bằng khen được treo đầy. Bên trái gian nhà là những tấm ảnh lưu niệm từ các bộ phim, vài dòng ký gửi đạo diễn và một vài tờ báo cắt ra nói về nhà cổ Bình Thủy.</p>



<p>Chính giữa nhà là một gian thờ lớn theo đúng kiểu người <strong>Nam bộ xưa</strong>. Bộ bài vị, lư hương, đèn đầy đủ. Đặc biệt, những kiến trúc chạm trổ của ngôi nhà đều rất tinh tế.</p>



<p>Nếu nhìn kỹ bạn sẽ nhận ra ngôi nhà điêu khắc khá nhiều động vật mang lại hưng thịnh theo quan điểm người xưa. Từ những thực vật như mai, sen, cúc, trúc, lan đến hình tượng động vật như lộc, dơi, chim, công, tôm, cua, rồng, phượng,&#8230;</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/đi-nhà-cổ-bình-thủy-du-lịch-nào-1024x682.jpg" alt="Đi nhà cổ Bình Thủy du lịch nào!" class="wp-image-3612" srcset="https://media.huynhhieutravel.com/đi-nhà-cổ-bình-thủy-du-lịch-nào.jpg 1024w, https://media.huynhhieutravel.com/đi-nhà-cổ-bình-thủy-du-lịch-nào-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Đi nhà cổ Bình Thủy du lịch nào!</figcaption></figure>



<p>Ngôi nhà cũng lưu giữ khá nhiều vật cổ với các bộ bàn ghế làm bằng đá cẩm thạch có xuất xứ từ Trung Quốc. Ngoài ra còn có bộ salon từ Pháp mang sang và cặp đèn treo từ thế kỷ 19.</p>



<p>Vào năm 2009, nhà cổ Bình Thủy đã được bộ Văn hóa &#8211; Thể thao và Du lịch công nhận Di tích kiến trúc nghệ thuật cấp quốc gia.</p>



<p>Hiện nhà cổ Bình Thủy vẫn do con cháu dòng họ Dương nằm giữ và lưu truyền. Nó cũng là ngôi nhà duy nhất còn thuộc sở hữu tư nhân trong 3 ngôi nhà cổ lớn và nổi tiếng ở miền Tây. Bên cạnh nó là nhà cổ <a rel="noreferrer noopener" aria-label="Công tử Bạc Liêu (mở trong tab mới)" href="https://huynhhieutravel.com/cong-tu-bac-lieu" target="_blank">Công tử Bạc Liêu</a> ở Bạc Liêu, nhà cổ Huỳnh Thủy Lê ở Đồng Tháp.</p>



<figure><iframe width="560" height="315" src="https://www.youtube.com/embed/t0NYGdv3yXA" allowfullscreen=""></iframe></figure>



<h2 class="wp-block-heading">Truyền kỳ về nhà cổ Bình Thủy</h2>



<p>Nhà cổ Bình Thủy là một kiến trúc mang đậm nét văn hóa nhà cổ của các phú hào ngày xưa ở miền Tây. Bên cạnh sự nổi tiếng từng là phim trường của nhiều bộ phim thì những <strong>truyền kỳ</strong> ở đây cũng thu hút nhiều người quan tâm.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/hình-ảnh-nhà-cổ-bình-thủy-cần-thơ-1024x682.jpg" alt="Hình ảnh nhà cổ Bình Thủy Cần Thơ" class="wp-image-3613" srcset="https://media.huynhhieutravel.com/hình-ảnh-nhà-cổ-bình-thủy-cần-thơ.jpg 1024w, https://media.huynhhieutravel.com/hình-ảnh-nhà-cổ-bình-thủy-cần-thơ-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Hình ảnh nhà cổ Bình Thủy Cần Thơ</figcaption></figure>



<h3 class="wp-block-heading">Lá bùa Lỗ Ban ếm phong thủy ngôi nhà</h3>



<p>Người ta đồn rằng, trên đòn dong hay đâu đó ở ngôi nhà cổ Bình Thủy này có ếm một lá bùa Lỗ Ban phong thủy. Nhờ vậy mà dòng họ Dương mới phất lên làm giàu nhanh chóng như vậy.</p>



<p>Tương truyền, lúc ấy trong vùng có ông Ba Nghĩa theo học nghề phong thủy Lỗ Ban (Người ta còn gọi ông Lỗ Ban). Lúc nào ra đường ông cũng quấn chiếc khăn điều màu đỏ chót lên đầu. Bên cạnh ông lúc nào cũng có chiếc riều và một cái nẻ mực (Đây là loại dây nhợ có tẩm mực tàu, dùng để tạo đường thẳng chặt gỗ hoặc đo đạc gỗ). </p>



<p>Bất kỳ một nhà phú hộ nào khi xây nhà đều phải nhờ ông &#8220;Lỗ Ban&#8221; đến xây cho nhà đẹp. Nhà họ Dương khi xây nhà cũng như vậy, phải mời thầy ấy lại thì nhà mới tốt. Nhưng nhà họ Dương lại đưa thêm một điều kiện khác.</p>



<p>&#8220;Thầy xây nhà tôi đẹp rực rỡ hay lung linh hơn nhà khác thì cũng thường quá. Tôi muốn là thầy xây nhà sao cho nhà tôi làm ăn khấm khá và giàu lên hơn như thế này mới được.&#8221;</p>



<p>Lúc ấy ông thầy Lỗ Ban đã có ý từ chối: &#8220;Khó nỗi cái nghề của tôi muốn gia chủ giàu thì mình phải cắn trả nghèo cùn nghèo mạt thì mới được.&#8221;</p>



<p>Ông Dương Chấn Kỷ khi nghe xong phất tay bảo: &#8220;Đừng lo, thầy cứ làm cho tôi. Mỗi tháng tôi sẽ chu cấp cho thầy 1 đấu gạo và 3 cắc bạc đến mãn đời&#8221;. Lúc ấy ông Ba Nghĩa Lỗ Ban trầm tư rồi mỉm cười đồng ý.</p>



<p><em><a href="https://dantri.com.vn/xem-an-choi/loi-nguyen-lo-ban-giai-ma-nhung-cam-bay-ky-di-nhat-cua-trung-hoa-co-dai-1366783452.htm" target="_blank" rel="noreferrer noopener nofollow" aria-label="Lỗ Ban (mở trong tab mới)">Lỗ Ban</a> trước đây là một bậc thầy về nghề mộc ở Trung Quốc. Ông có tay nghề khéo léo cùng với khả năng phong thủy tuyệt vời. Những người làm nghề Lỗ Ban trước đây ở Việt Nam luôn là những bậc cao tay ấn về phong thủy. Nhưng tương truyền làm nghề Lỗ Ban cũng chịu cắn trả cực kỳ thảm khốc.</em></p>



<p><em>Bạn phải nuôi một con ngãi, chuyên phục vụ cho mình. Quy luật của nó là cân bằng. Nếu gia hại người khác thì bạn sẽ tạo thói quen cho nó. Từ đó nó sẽ cắn trả lại người nuôi liên tục. Nếu người Lỗ Ban chết đi, nó sẽ lưu truyền theo huyết mạch. Hoặc nếu muốn làm giàu người khác, người Lỗ Ban cũng chịu phản ngược lại. </em></p>



<p>Mình chỉ ghi lại một góc cạnh của nghề Lỗ Ban cho bạn biết. Nó có thể chưa đủ hoặc đôi chút sai lệch vì mình chỉ nghe người khác kể lại. Nghề Lỗ Ban hiện giờ vẫn còn ở Việt Nam nhưng khá hiếm vì tỷ lệ thất truyền khá cao.</p>



<h3 class="wp-block-heading">Câu chuyện về bảy bộ ghế đá sau vườn</h3>



<p>Năm 1945, thực dân Pháp xâm lược nước ta <a rel="noreferrer noopener nofollow" aria-label="lần 2 (mở trong tab mới)" href="https://alphahistory.com/vietnamwar/vietnam-war-timeline-1946-1954/" target="_blank">lần 2</a>. Nhà nước lâm thời lúc bấy giờ phát động toàn dân kháng chiến. Vào tháng 12 năm 1945, quân đội ta ở Cần Thơ đụng độ quân Pháp. Lúc ấy tiếng súng nổ vang cả trời, thỉnh thoảng những tiếng lựu đạn lại nổ ầm ầm. tô điểm thêm sự ác liệt của cuộc đấu súng đôi bên. Chúng ta phục kích tiêu diệt nhiều sĩ quan Pháp nhưng cũng hy sinh hết 7 người lính anh dũng.</p>



<p>Lúc ấy, để tưởng nhớ chiến công và sự hy sinh anh dũng của 7 người lính. Ông Dương Văn Ngôn đã cho xây dựng 7 bộ ghế đá. Khi xây xong, quân Pháp đã tra hỏi nhưng ông chỉ bảo đây là chỉ bảy vị thất hiền của Trung Quốc xưa. Nên quân Pháp cũng không thể làm gì được ông.</p>



<h3 class="wp-block-heading">Cây xương rồng ở nhà cổ Bình Thủy</h3>



<p>Cây xương rồng này được nhập từ Mexico về. Nó được đặt ở trước một quán cafe trong khuôn viên của nhà cổ Bình Thủy. Cây xương rồng cao hơn 10m với độ tuổi xấp sỉ 40 năm. Đây là loại hiếm và khó tìm thấy được ở Việt Nam bây giờ.</p>



<h3 class="wp-block-heading">Phim trường của nhiều bộ phim nổi tiếng</h3>



<p>Nhà cổ Bình Thủy là một trong 3 ngôi nhà cổ lớn nhất và còn nguyên vẹn hiếm hoi ở miền Tây. Nó mang trong mình giá trị văn hóa và lịch sử lâu đời. Vì vậy, những bộ phim nói về thời xưa ở Việt Nam thường lựa chọn nó làm phim trường để quay.</p>



<p>Những bộ phim Việt Nam nổi tiếng từng quay ở đây như Người đẹp Tây Đô, Những nẻo đường phù sa, Nợ đời,&#8230; Hay cả bộ phim nước ngoài kinh điển nổi tiếng lúc bấy giờ là <a rel="noreferrer noopener nofollow" aria-label="The Lover (mở trong tab mới)" href="https://www.imdb.com/title/tt0101316/" target="_blank">The Lover</a> (1992). Bộ phim kể về mối tình có thật của vị thiếu gia con nhà Huỳnh Thủy Lê cùng một cô gái người Pháp. Bộ phim được tài tử nổi tiếng của Hong Kong lúc bấy giờ là Lương Gia Huy đóng chính.</p>



<h2 class="wp-block-heading">Tham quan nhà cổ Bình Thủy</h2>



<p>Nhà cổ Bình Thủy hàng năm đón hàng chục ngàn du khách tham quan khi đến Cần Thơ. Nếu bạn muốn nghe thuyết minh nhiều hơn về nhà cổ Bình Thủy thì có thể nghe ké hướng dẫn viên đi cùng đoàn khách khi vào. Hoặc bạn có thể book tour du lịch thành phố Cần Thơ để có <strong>hướng dẫn viên đi cùng</strong>. Trong đó chắc chắn có tour nhà cổ Bình Thủy. Bạn cũng có thể tham khảo tour Cần Thơ 1 ngày <a rel="noreferrer noopener" aria-label="tại đây (mở trong tab mới)" href="https://nucuoimekong.com/tour/tour-can-tho-1-ngay/" target="_blank">tại đây</a>.</p>



<figure class="wp-block-image"><img loading="lazy" decoding="async" width="1024" height="682" src="https://media.huynhhieutravel.com/thông-tin-nhà-cổ-bình-thủy-1024x682.jpg" alt="Thông tin nhà cổ Bình Thủy" class="wp-image-3606" srcset="https://media.huynhhieutravel.com/thông-tin-nhà-cổ-bình-thủy.jpg 1024w, https://media.huynhhieutravel.com/thông-tin-nhà-cổ-bình-thủy-768x512.jpg 768w" sizes="(max-width: 1024px) 100vw, 1024px" /><figcaption>Thông tin về ngôi nhà này</figcaption></figure>



<h3 class="wp-block-heading">Giá vé tham quan nhà cổ Bình Thủy</h3>



<p>Nếu bạn chỉ đứng khuôn viên bên ngoài tham quan thì miễn phí. Nhưng nếu bước vào bên trong nhà bạn phải đóng <strong>15.000đ</strong> cho người quản lý ở đó.</p>



<h3 class="wp-block-heading">Giờ mở cửa nhà cổ Bình Thủy</h3>



<p><strong>Giờ tham quan nhà cổ Bình Thủy</strong>: 8h00 &#8211; 12h00 và 14h00 &#8211; 18h00.</p>



<h3 class="wp-block-heading">Địa chỉ nhà cổ Bình Thủy</h3>



<p>Nhà cổ Bình Thủy cách trung tâm thành phố khoảng <strong>10km</strong>. Đường khá dễ đi, bạn chỉ cần qua cầu Bình Thủy và quẹo vào bên trái một khu chợ và chạy thẳng. Bạn có thể đến đó hỏi bất kỳ người dân địa phương nào đều biết hướng dẫn bạn đường đi đến nhà cổ Bình Thủy.</p>



<p><strong>Địa chỉ</strong>: 144 Bùi Hữu Nghĩa, Bình Thuỷ, Bình Thủy, Cần Thơ.</p>



<figure><iframe src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d39593.67577705768!2d105.7314403101988!3d10.08350168968795!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xdd6d2b33fcb3c628!2zTmjDoCBj4buVIELDrG5oIFRo4buneQ!5e0!3m2!1svi!2s!4v1546992270900" width="600" height="450" allowfullscreen=""></iframe></figure>



<p>Ngoài ra, bạn cũng có thể tham khảo kinh nghiệm du lịch Cần Thơ, địa điểm, ăn gì ở đây: <a href="https://huynhhieutravel.com/du-lich-can-tho">https://huynhhieutravel.com/du-lich-can-tho</a></p>



