', 'Thác Pongour là một địa điểm du lịch hấp dẫn với du khách khi đến Đà Lạt. Nó đặc biệt thu hút nhiều khách du lịch nước ngoài đến khám phá. Nó cũng từng được vua Bảo Đại phong tặng là &#8220;Nam thiên đệ nhất thác&#8220;. Thác gồm 7 tầng với độ cao hơn 40m [&hellip;]', 1787, 'post', '2018-09-08 07:19:55', '2023-04-23 12:46:45');
